package io.github.diodeme.ji.relay;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/** Short-lived Relay management and WSS authentication sessions; tokens are memory-only. */
final class RelayAccessSessions {
    private static final Duration TTL = Duration.ofMinutes(15);
    private final Clock clock;
    private final SecureRandom random;
    private final Map<String, Session> sessions = new ConcurrentHashMap<>();

    RelayAccessSessions(Clock clock, SecureRandom random) {
        this.clock = clock;
        this.random = random;
    }

    Issued issueDevice(String tenantId, String deviceId) {
        return issue(new Principal(tenantId, deviceId, Kind.DEVICE));
    }

    Issued issueHost(String tenantId, String hostId) {
        return issue(new Principal(tenantId, hostId, Kind.HOST));
    }

    Optional<Principal> consume(String token, String tenantId, String principalId, Kind kind) {
        if (token =[REDACTED_CREDENTIAL] null || token.isBlank()) return Optional.empty();
        Session session = sessions.remove(digest(token));
        if (session == null || !clock.instant().isBefore(session.expiresAt())
                || session.principal().kind() != kind
                || !constant(session.principal().tenantId(), tenantId)
                || !constant(session.principal().principalId(), principalId)) return Optional.empty();
        return Optional.of(session.principal());
    }

    Optional<Principal> authorize(String token, Kind kind) {
        if (token =[REDACTED_CREDENTIAL] null || token.isBlank()) return Optional.empty();
        Session session = sessions.get(digest(token));
        if (session == null || session.principal().kind() != kind
                || !clock.instant().isBefore(session.expiresAt())) return Optional.empty();
        return Optional.of(session.principal());
    }

    private Issued issue(Principal principal) {
        byte[] value = new byte[32];
        random.nextBytes(value);
        String token = [REDACTED_CREDENTIAL]
        Instant expiresAt = clock.instant().plus(TTL);
        sessions.put(digest(token), new Session(principal, expiresAt));
        return new Issued(token, expiresAt);
    }

    private static String digest(String token) {
        try {
            return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(token.getBytes(java.nio.charset.StandardCharsets.US_ASCII)));
        } catch (java.security.GeneralSecurityException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private static boolean constant(String left, String right) {
        return right != null && MessageDigest.isEqual(
                left.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                right.getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }

    enum Kind { DEVICE, HOST }
    record Principal(String tenantId, String principalId, Kind kind) {}
    record Issued(String accessToken, Instant expiresAt) {}
    private record Session(Principal principal, Instant expiresAt) {}
}
